import re

NESTED = re.compile(r"(a+)+$")
WORDS = re.compile(r"^(\w+\s?)*$")
ALTERNATIVE = re.compile(r"(x|y+)+z")
BOUNDED_MINIMUM = re.compile(r"(?:a+){2,}b")
NAMED = re.compile(r"(?P<word>[a-z]+)*!")
LAZY = re.compile(r"((\d)*?)*?x")
INNER = re.compile(r"x(?:y(a+)+)z")
VERBOSE = re.compile(
    r"""
    (\w+  # word
     \s?)*
    $
    """,
    re.VERBOSE,
)
INLINE_VERBOSE = re.compile(r"(?x) ( a + ) + $")
SEPARATED = re.compile(r"(\d+\.)+\d+")
TWO_REPEATS = re.compile(r"(a+b+)+")
POSSESSIVE = re.compile(r"(a+)++")
INNER_POSSESSIVE = re.compile(r"(a++)+")
ATOMIC = re.compile(r"(?>a+)+")
BOUNDED = re.compile(r"(a+){3}")
OPTIONAL = re.compile(r"(a+)?")
CLASS = re.compile(r"([]a-z\]]+)c")
NEGATED_CLASS = re.compile(r"([^]a]+)c")
LITERAL_BRACE = re.compile(r"(a+){x}")
EMPTY_BRACE = re.compile(r"a{,}")
UPPER_BOUND = re.compile(r"(a+){,5}")
LOOKAHEAD = re.compile(r"(?=a+)+")
LOOKBEHIND = re.compile(r"((?<=a)b)+")
COMMENT = re.compile(r"(?#note)a+")
BACKREFERENCE = re.compile(r"(?P<x>a)(?P=x)+")
CONDITIONAL = re.compile(r"(a)?(?(1)(b+)+|c)")
SCOPED_VERBOSE = re.compile(r"(?x:(a+)+)")
FLAGS = re.compile(r"(?i)(a+)+")
SCOPED_FLAGS = re.compile(r"(?i:(a+)+)")
BAD_FLAG = re.compile(r"(?Z)")
UNBALANCED = re.compile(r"(a+")
EXTRA_CLOSE = re.compile(r"a)")
OPTIONAL_INNER = re.compile(r"((a*)?)+b")
UNBOUNDED_BRACE = re.compile(r"(a+){,}b")
NESTED_GROUP = re.compile(r"((?:a+)b?)+c")
LITERAL_COMMAS = re.compile(r"(a+){1,2,3}")
# A bad group name makes the scan and the parser read past it differently; each pattern is left unreported.
NAME_HIDES_CLASS = re.compile(r"(?P<a[>[]")
NAME_HIDES_COMMENT = re.compile(r"(?P<a[>(?#x]")
NAME_HIDES_REFERENCE = re.compile(r"(?P<a[>(?P=x]")
UNCLOSED_NAME = re.compile(r"(?P<a)")
FLAGS_AT_END = re.compile(r"(?i")
CONDITIONAL_IN_GROUP = re.compile(r"(a)((?(1)b))")
ANGLE_NAME = re.compile(r"(?<w>a+)+")
UPPER_NAME = re.compile(r"(?<Word>a+)+")
UNCLOSED_COMMENT = re.compile(r"(?#note")
UNCLOSED_CONDITION = re.compile(r"(?(1")
UNCLOSED_BRACE = re.compile(r"(a+){2")
BYTES_BRACE = re.compile(b"(a+){\xff}")
HUGE_MINIMUM = re.compile(r"(a+){99999999999}")
UNCLOSED_REFERENCE = re.compile(r"(a)(?P=x")
# Nothing after the repeat can fail, so the first way it matches ends the search.
TAIL_EMPTY = re.sub(r"[.]a([.]?([0-9]+))*([.]?([a-z]+))*", "", "1.a1")
TAIL_ANCHORED = re.sub(r"[.]a([.]?([0-9]+))*$", "", "1.a1")
TAIL_LOOKAHEAD = re.search(r"(a+)+(?=b)", "aab")
TAIL_FULL = re.fullmatch(r"(a+)+", "aa")
